    "question": "一家國際銀行總部位於西班牙馬德里，並在美國紐約市 (NYC) 設有辦事處。馬德里辦事處正在調查一筆來自其紐約辦事處一位元客戶的交易，並詢問紐約辦事處是否可以分享該客戶的進一步相關資訊。經過進一步調查，紐約辦事處發現他們在過去一年中已向該客戶提交了一份可疑活動報告 (SAR)。在共用所需資訊之前需要考慮哪些因素？（選兩項）",
